"""Freeze proposed small comparison settings and initialization; never fit."""
from pathlib import Path
import hashlib,json,csv,sys
import numpy as np
import torch
ROOT=Path(__file__).resolve().parents[2];sys.path[:0]=[str(ROOT/'src/preprocessing'),str(ROOT/'src/analyses')]
from prepare_three_ward_unet_exact_pilot import OUT as SOURCE,REPORT as SOURCE_REPORT,sha,read,write,arrays,load_label
from train_three_ward_unet_exact_pilot import ConditionalUNet
from three_ward_surrogate_protocol_v2 import LOSS_WEIGHTS
NAME='three_ward_unet_control_plan_v2';OUT=ROOT/'data/processed'/NAME;REPORT=ROOT/'data/exp/estimation'/NAME

def mask_sha(m):return hashlib.sha256(np.ascontiguousarray(m,dtype='u1').tobytes()).hexdigest()
def main():
 OUT.mkdir(parents=True,exist_ok=True);REPORT.mkdir(parents=True,exist_ok=True)
 if (OUT/'protocol.json').exists():raise FileExistsError('Prepared plan already exists')
 p=read(SOURCE/'protocol.json');freeze=read(SOURCE/'freeze.json');assert all(sha(ROOT/k)==v for k,v in freeze['files_sha256'].items())
 previous=ROOT/'data/processed/three_ward_unet_shallow_diagnosis_v1/freeze.json';df=read(previous);assert all(sha(ROOT/k)==v for k,v in df['files_sha256'].items())
 z=arrays(SOURCE/'prepared_inputs.npz');choices={r['case_id']:r for r in csv.DictReader((SOURCE_REPORT/'retrieval_choices.csv').open())};records=[];masks={r['case_id']:load_label(r['case_id'],r['split'])['Exact Label Mask']&z['Eligible Ground Mask'] for r in p['records']}
 for r in p['records']:
  q=choices[r['case_id']];j=next(v for v in p['records'] if v['case_id']==q['source_case_id']);assert j['split']=='train' and j['family_id']!=r['family_id']
  pair=masks[r['case_id']]&masks[j['case_id']];records.append(r|{'original_exact_eligible_mask_sha256':mask_sha(masks[r['case_id']]),'retrieval_source_case_id':j['case_id'],'paired_exact_mask_sha256':mask_sha(pair),'paired_three_ward_mask_sha256':mask_sha(pair&(z['Ward Code']>0))})
 train=[r['case_id'] for r in records if r['split']=='train'];validation=[r['case_id'] for r in records if r['split']=='validation'];assert len(train)==12 and len(validation)==4
 rng=np.random.default_rng(p['seed']);order=[{'epoch':epoch,'case_order':list(rng.permutation(train))} for epoch in range(1,41)];write(OUT/'epoch_order.json',order)
 torch.manual_seed(p['seed']);model=ConditionalUNet();assert sum(v.numel() for v in model.parameters())==671513
 torch.save({'state_dict':model.state_dict(),'seed':p['seed'],'trained':False,'optimizer_steps':0,'architecture_source_sha256':sha(ROOT/'src/analyses/train_three_ward_unet_exact_pilot.py')},OUT/'shared_initialization.pt')
 arms=[]
 for aid,loss,lr in [('A_mse_original_lr','mse',.001),('B_huber_original_lr','stratified_huber',.001),('C_mse_lower_lr','mse',.0003),('D_huber_lower_lr','stratified_huber',.0003)]:
  arms.append({'arm_id':aid,'loss':loss,'learning_rate':lr,'seed':p['seed'],'maximum_epochs':40,'maximum_optimizer_updates':480,'status':'planned_not_started'})
 sourcepaths=[SOURCE/'protocol.json',SOURCE/'freeze.json',SOURCE/'normalization.json',SOURCE/'prepared_inputs.npz',SOURCE_REPORT/'retrieval_choices.csv',previous,ROOT/'src/analyses/train_three_ward_unet_exact_pilot.py',ROOT/'src/preprocessing/prepare_three_ward_unet_exact_pilot.py']
 protocol={'version':NAME,'decision':'MILI-D-20261016-004','status':'prepared_not_executed','execution_authorized':False,'fit_runs_executed':0,'optimizer_updates_executed':0,'sealed_access':False,'settings_ownership':'Concrete engineering proposal for review under authorized preparation; not a record that the human separately selected each numeric setting. No fit is authorized by preparing this plan.','records':records,'train_case_ids':train,'validation_case_ids':validation,'arms':arms,'contrasts':{'loss_at_original_lr':['A_mse_original_lr','B_huber_original_lr'],'loss_at_lower_lr':['C_mse_lower_lr','D_huber_lower_lr'],'lr_with_mse':['A_mse_original_lr','C_mse_lower_lr'],'lr_with_huber':['B_huber_original_lr','D_huber_lower_lr'],'interaction':'Descriptive difference of the two loss contrasts; single seed, four validation parents, no inferential population claim.'},'frozen_common_settings':{'architecture':'Unchanged full-domain conditional U-Net, 671513 parameters, same Softplus, 58 static channels and 1920 conditioning values','initialization_sha256':sha(OUT/'shared_initialization.pt'),'epoch_order_sha256':sha(OUT/'epoch_order.json'),'normalization_sha256':sha(SOURCE/'normalization.json'),'prepared_inputs_sha256':sha(SOURCE/'prepared_inputs.npz'),'seed':p['seed'],'optimizer':'AdamW','weight_decay':.00001,'gradient_clip':10.,'batch_size':1,'epochs':40,'early_stopping':False,'learning_rate_schedule':'constant in each arm; no simultaneous scheduler change','augmentation':False,'target_scaled':False,'test_seeds':1,'maximum_total_fits':4,'maximum_total_optimizer_steps':1920,'interpretation':'Fixed budget for comparison, not a promise of convergence. No architecture, output-head, target scaling or data expansion treatment.'},'loss':{'reference':'Original exact-mask, Ground Area weighted per-event MSE','candidate':'Within-stratum area-weighted 2*Huber(delta=0.10m), then fixed mixture; squared below residual0.10m, linear tails','units':'metres squared for both losses','strata':{'nonwet':'reference<=0.10m','ordinary_wet':'0.10m<reference<=1.00m','deep':'reference>1.00m'},'weights':LOSS_WEIGHTS,'absent_stratum':'Renormalize over present strata; record absence, not zero error or a fabricated target','empty_event':'Fail, never manufacture zero loss','target_contract':'Original exact masks and bounds unchanged; no unknown/interval/quarantined regression targets','weight_rationale':'A half-weight nonwet term retains false-positive pressure, ordinary wet gains a separate term, deep tails remain supervised with linear residual influence. Weights and delta are fixed proposals, not proven optimal or fitted from validation.'},'metrics':{'mask_binding':'Each metric frame carries the SHA256 of its entire support mask; checkpoint selection and baseline guards verify it against the frozen paired support.','threshold_precision':'Classify prediction/reference in their native incoming dtype before float64 error/area aggregation; preserve original float32 comparison behaviour.','wet_threshold':.1,'sensitivity_thresholds':[.05,.3,.5],'primary':'Per-event balanced extent error =0.5*(FNR+FPR), then equal parent macro average','FNR':'FN/(TP+FN), reference-wet area denominator','FPR':'FP/(FP+TN), reference-nonwet area denominator; distinct from false discovery','additional':['MAE','RMSE','bias','nonwet/ordinary-wet/deep/wet MAE and defined-parent counts','IoU','precision','recall','false discovery','false and missed square kilometres','support/abstention coverage'],'scopes':['whole domain','three wards','Chiyoda','Chuo','Minato','cross-ward contributing area'],'invalid_active_prediction':'Fail rather than silently omit; zero-area and original excluded support never targets','empty_class':'Undefined rates remain null; never perfect. A checkpoint with undefined primary validation class cannot rank.'},'checkpoint':{'evaluation_frequency':'Every epoch after all 12 updates, fixed model, train and validation evaluated separately; no update during scoring','primary_scope':'three_wards','primary_support':'paired_exact fixed by target original exact AND original training-only retrieval source exact AND eligible AND three-ward support','supplementary':'Full target exact support and all geographic scopes; no scoring-only mask changes','ranking':['lowest macro balanced extent error','lowest macro reference-wet MAE','lowest macro overall MAE','earliest epoch'],'tie_resolution':'Round metric entries to6 decimal places (dimensionless or metres) for a fixed total order before epoch tie-break','retention':'Save every epoch state dict; latest optimizer/RNG state; immutable checkpoint index with hashes, clock, score, support, all parent metrics and failed guards','baseline_guard':'For each of all4 validation parents: balanced extent error no worse than retrieval; MAE no worse than both dry and retrieval; recall no worse than retrieval; false area no worse than retrieval. Numeric comparisons tolerance1e-6 (rates/metres/square kilometres as applicable). A chosen diagnostic checkpoint is not an admitted/usable model if any guard fails.','failed_all':'Keep diagnostic best plus explicit not_ready; no fallback that changes limits or opens tests','normalization_and_retrieval':'Reuse frozen train-only normalization and original train-only nearest choices; no validation candidates or self-family retrieval'},'telemetry':{'aggregation_interface':'Complete per-epoch parent exposure, contiguous optimizer step counts, online pre-update loss, gradient distributions, clipping count and module update distributions. Interface-probe records are segregated from training updates.','per_optimizer_update':['arm, epoch, parent/family/forcing identifiers, split, seed, exact-mask hash and protocol hash','online pre-update loss and each stratum contribution/area/weight','preclip and postclip gradient total/module norms, finite flags and missing gradients','clip threshold and clipping indicator','actual parameter update norm and parameter norm per module','optimizer step before/after, learning rate, timing scope'],'per_epoch':['Fixed-checkpoint train/validation metrics on paired/full exact support by event and region','actual update count and cumulative optimizer/training/evaluation/checkpoint-I/O clocks','loss and gradient distributions, clipping count, checkpoint hash and ranking/readiness results'],'not_interchangeable':'Online sequential-update mean loss and fixed end-of-epoch loss have distinct fields','failures':'Stop and preserve failure receipt on nonfinite active support, loss, gradient, broken masks/lineage/version, or optimizer clock mismatch; never repair by silently dropping cells','status_for_this_task':'Only schema and zero-update interface records; no historical/future update evidence fabricated'},'implementation_sha256':{str(q.relative_to(ROOT)):sha(q) for q in [ROOT/'src/analyses/three_ward_surrogate_protocol_v2.py',Path(__file__)]},'source_sha256':{str(q.relative_to(ROOT)):sha(q) for q in sourcepaths},'limitations':['Validation used for diagnosis and future selection is development data; not an independent test.','One seed cannot measure optimization variability; no architecture or dataset-sufficiency result follows.','Peak fields do not demonstrate dynamic mass conservation, simultaneous flooding or drainage paths.','No new hydraulic simulations, interval-aware fit, graph fit, sealed/challenge responses or active measures.','Historical original fit is context, not one of the equal-budget new controls.']}
 write(OUT/'protocol.json',protocol);write(REPORT/'preparation_receipt.json',{'decision':protocol['decision'],'arms':len(arms),'training_parents':12,'validation_parents':4,'new_fits':0,'optimizer_updates':0,'sealed_opened':False,'protocol_sha256':sha(OUT/'protocol.json')});print(json.dumps({'arms_prepared':4,'new_fits':0,'future_total_step_cap':1920}))
if __name__=='__main__':main()
